/* The text for a key in the chosen language; {0}, {1} are filled from the arguments. An unknown key comes back as itself. */
function t(key, ...args) {
  const row = (args[0] === 1 && STRINGS[key + ".one"]) || STRINGS[key];  // "1 occupation", not "1 occupations"
  if (!row) return key;
  return (row[LANG_INDEX[LANG]] || row[0]).replace(/\{(\d+)\}/g, (_, i) => (args[i] === undefined || args[i] === null ? "" : args[i]));
}
/* A UN goal name in the chosen language; anything else unchanged. */
function nameOf(english) {
  const row = NAMES[english];
  return LANG === "en" || !row ? english : row[LANG_INDEX[LANG] - 1];
}
/* What a UN goal ("16") or target ("16.3") means; a target with no line falls back to its goal. */
function sdgText(target) {
  const row = SDG_TEXT[String(target)] || SDG_TEXT[String(target).split(".")[0]];
  return row ? row[LANG_INDEX[LANG]] : "";
}
function setLang(next) {
  LANG = next === "ms" || next === "zh" ? next : "en";
  try { localStorage.setItem(LANG_KEY, LANG); } catch (e) { /* storage off */ }
}
